DROP TABLE IF EXISTS `fttwp_woocommerce_sessions`;
CREATE TABLE `fttwp_woocommerce_sessions` (
  `session_id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `session_key` char(32) COLLATE utf8mb4_unicode_ci NOT NULL,
